mapper.select:
select t.name,t.type_id,t.type_id typeId,t.status_cd,t.status_cd statusCd,t.remark,t.community_id,t.community_id
communityId,t.create_time createTime
from instrument_type t
where 1 =1

    and t.name like concat('%', #{name}, '%')


    and t.type_id like concat('%', #{typeId}, '%')


    and t.status_cd= #{statusCd}


    and t.remark= #{remark}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
